1	package agentusage
2	
3	import (
4		"cmp"
5		"errors"
6		"fmt"
7		"io"
8		"os"
9		"path/filepath"
10		"slices"
11		"strings"
12		"sync/atomic"
13		"time"
14	)
15	
16	// fileCursor is the read position of one transcript. Values only: no pointer
17	// except the immutable os.FileInfo.
18	type fileCursor struct {
19		path     string      // full path, never logged
20		name     string      // sanitized base name (FileIssue.File, TruncatedFiles)
21		agent    string      // key of the agent in a table: "" for the parent, else rank
22		label    string      // sanitized agent ID shown to the user; "" for the parent
23		rank     string      // position rank of the file (parentRank or transcriptRank)
24		id       os.FileInfo // from the open handle's Stat at the last read; nil before
25		offset   int64       // just past the last complete line folded in
26		size     int64       // file size at the last read
27		modTime  time.Time   // Lstat mtime at the last listing
28		skipFrom int64       // start of an oversized line still being written, or -1
29		tail     bool        // an incomplete line follows offset (TruncatedFiles)
30		issue    IssueKind   // state issue of the last read (D6), valid if hasIssue
31		issueOff int64
32		hasIssue bool
33	}
34	
35	// newFileCursor returns the cursor of a transcript not read yet.
36	func newFileCursor(path, name, agent, rank string) fileCursor {
37		return fileCursor{path: path, name: name, agent: agent, rank: rank, skipFrom: -1}
38	}
39	
40	// transcriptFile is what readFile needs from an open transcript; *os.File
41	// satisfies it.
42	type transcriptFile interface {
43		io.Reader
44		io.ReaderAt
45		io.Seeker
46		io.Closer
47		Stat() (os.FileInfo, error)
48	}
49	
50	// openTranscript opens a transcript through openPlain. A var so tests can
51	// count opens and bytes read.
52	var openTranscript = func(path string) (transcriptFile, error) {
53		f, err := openPlain(path, false)
54		if err != nil {
55			return nil, err
56		}
57		if f == nil {
58			return nil, errNotRegular
59		}
60		return f, nil
61	}
62	
63	// fileRead is the outcome of reading one file from its cursor.
64	type fileRead struct {
65		next  fileCursor
66		part  *table // lines folded from the new bytes; nil when nothing was read
67		reset bool   // not an append (D4): the caller restarts the whole session
68		err   error  // why the file could not be opened or read at all, if so
69	}
70	
71	// read reports whether the cursor has already read part of its file.
72	func (fc fileCursor) read() bool { return fc.offset > 0 || fc.skipFrom >= 0 || fc.id != nil }
73	
74	// quiet reports whether the file is, as far as Lstat can tell, exactly what the
75	// last read saw. A cursor holding a read error never is: the bytes between
76	// its offset and the failure must be read again.
77	func (fc fileCursor) quiet(li os.FileInfo) bool {
78		if fc.id == nil || (fc.hasIssue && fc.issue == IssueReadError) {
79			return false
80		}
81		return li.Size() == fc.size && os.SameFile(li, fc.id)
82	}
83	
84	// failRead is the outcome of a path that cannot be read: a reset when the file
85	// was read before (D4), else a state issue cleared by the next success (D6).
86	func failRead(fc fileCursor, err error) fileRead {
87		if fc.read() {
88			return fileRead{next: fc, reset: true, err: err}
89		}
90		fc.issue, fc.issueOff, fc.hasIssue = IssueOpenFailed, 0, true
91		return fileRead{next: fc, err: err}
92	}
93	
94	// isAppend reports whether the open file is the one fc read, only grown (D4).
95	func (fc fileCursor) isAppend(f transcriptFile, fi os.FileInfo) bool {
96		if (fc.id != nil && !os.SameFile(fi, fc.id)) || fi.Size() < fc.size {
97			return false
98		}
99		if fc.offset == 0 {
100			return true
101		}
102		var b [1]byte
103		n, _ := f.ReadAt(b[:], fc.offset-1)
104		return n == 1 && b[0] == '\n'
105	}
106	
107	// readFile reads what was appended to fc's file since fc. now clamps mtimes.
108	// It never follows a link and never opens a non-regular file.
109	func readFile(fc fileCursor, now time.Time) fileRead {
110		li, err := os.Lstat(fc.path)
111		if err != nil {
112			return failRead(fc, err)
113		}
114		if !li.Mode().IsRegular() {
115			return failRead(fc, errNotRegular)
116		}
117		fc.modTime = li.ModTime()
118		if fc.modTime.After(now) {
119			fc.modTime = now
120		}
121		if fc.quiet(li) {
122			return fileRead{next: fc}
123		}
124		f, err := openTranscript(fc.path)
125		if err != nil {
126			return failRead(fc, err)
127		}
128		defer func() { _ = f.Close() }()
129		fi, err := f.Stat()
130		if err != nil {
131			return failRead(fc, err)
132		}
133		if !fc.isAppend(f, fi) {
134			return fileRead{next: fc, reset: true}
135		}
136		return fc.scan(f, fi)
137	}
138	
139	// scan folds the lines past the cursor into a new table and returns the
140	// advanced cursor. A line held back is read again next time (D1); an
141	// oversized one still being written is resumed in skip mode (D2).
142	func (fc fileCursor) scan(f transcriptFile, fi os.FileInfo) fileRead {
143		start := fc.offset
144		if fc.skipFrom >= 0 {
145			start = fc.size
146		}
147		if _, err := f.Seek(start, io.SeekStart); err != nil {
148			return failRead(fc, err)
149		}
150		part := newTable()
151		res, err := scanFrom(f, start, fc.skipFrom, MaxLineBytes, func(line []byte, off int64) {
152			part.addLine(fc.agent, fc.name, pos{rank: fc.rank, off: off}, line)
153		})
154		for _, off := range res.OversizedAt {
155			part.addOversized(fc.name, pos{rank: fc.rank, off: off})
156		}
157		next := fc
158		next.id, next.size, next.skipFrom = fi, res.End, res.SkipFrom
159		next.offset, next.tail = res.Consumed, len(res.Tail) > 0
160		if fc.skipFrom >= 0 && res.Consumed == start {
161			next.offset = fc.offset // the oversized line has not ended yet
162		}
163		next.issue, next.issueOff, next.hasIssue = 0, 0, false
164		if err != nil {
165			next.issue, next.issueOff, next.hasIssue = IssueReadError, next.offset, true
166		}
167		return fileRead{next: next, part: part}
168	}
169	
170	// ErrStaleDelta is returned by Apply for a delta that was not read from the
171	// aggregate's current cursor. The aggregate is unchanged; read again from
172	// Cursor().
173	var ErrStaleDelta = errors.New("agentusage: delta does not follow the aggregate's cursor")
174	
175	// readMetaFile reads one meta file; a var so tests can count meta reads (D7).
176	// The session reader goes through it.
177	var readMetaFile = readMeta
178	
179	// timeNow is time.Now; a var for tests.
180	var timeNow = time.Now
181	
182	// aggregateIDs hands out the identity of each Aggregate (D9).
183	var aggregateIDs atomic.Uint64
184	
185	// metaCursor is the last listing of one sub-agent's meta file and what was
186	// read from it. Values only, so a cursor stays a plain copyable value.
187	type metaCursor struct {
188		rank       string // rank of the sub-agent's transcript
189		path       string // "" when absent
190		size       int64
191		modTime    time.Time
192		unreadable bool
193		typ        string
194		state      State
195		depth      int
196	}
197	
198	// sameResult reports whether o tells the same story as m: Lstat details such
199	// as the mtime are not part of it.
200	func (m metaCursor) sameResult(o metaCursor) bool {
201		return m.rank == o.rank && (m.path == "") == (o.path == "") && m.unreadable == o.unreadable &&
202			m.typ == o.typ && m.state == o.state && m.depth == o.depth
203	}
204	
205	// unchangedSince reports whether the file Lstat described by fi is the one m
206	// was read from.
207	func (m metaCursor) unchangedSince(path string, fi os.FileInfo) bool {
208		return fi != nil && m.path == path && m.size == fi.Size() && m.modTime.Equal(fi.ModTime())
209	}
210	
211	// Cursor records how far each file of one session has been read. It is a
212	// plain value: copying it is safe and ReadDelta never mutates it. It holds
213	// full paths, so it must never be logged; String and GoString redact them.
214	type Cursor struct {
215		parent string // parent transcript path
216		id     uint64 // identity of the aggregate it came from
217		seq    uint64 // number of deltas applied when it was taken
218		fresh  bool   // nothing applied yet, or rewound: the next delta is Full
219		files  []fileCursor
220		metas  []metaCursor
221	}
222	
223	// Rewound returns c with every position cleared, keeping its identity: the
224	// next ReadDelta reads every file from the start and returns a Full delta.
225	func (c Cursor) Rewound() Cursor {
226		files := make([]fileCursor, len(c.files))
227		for i, fc := range c.files {
228			files[i] = newFileCursor(fc.path, fc.name, fc.agent, fc.rank)
229			files[i].label = fc.label
230		}
231		c.files, c.metas, c.fresh = files, nil, true
232		return c
233	}
234	
235	// String redacts the paths the cursor holds.
236	func (c Cursor) String() string { return fmt.Sprintf("agentusage.Cursor{files: %d}", len(c.files)) }
237	
238	// GoString redacts the paths the cursor holds.
239	func (c Cursor) GoString() string { return c.String() }
240	
241	// Delta is what ReadDelta found since a Cursor: the new complete lines of each
242	// file, already deduplicated, the files that appeared, the meta files that
243	// changed, and the positions to resume from. Paths live in unexported fields
244	// and are never printed.
245	type Delta struct {
246		valid     bool   // false for the zero Delta, which was never read
247		id, seq   uint64 // the cursor it was read from
248		full      bool
249		changed   bool
250		sessionID string
251		files     []fileCursor
252		metas     []metaCursor
253		part      *table
254		parentErr error // why the parent could not be opened, for ParseSession
255	}
256	
257	// Full reports whether the delta was read from the start of every file (first
258	// read, Rewound cursor, or a change that was not an append).
259	func (d Delta) Full() bool { return d.full }
260	
261	// Empty reports whether nothing changed: no new line, no file added or gone,
262	// no meta change. A file whose mtime alone moved does not count.
263	func (d Delta) Empty() bool { return !d.changed }
264	
265	// String shows counts only.
266	func (d Delta) String() string {
267		return fmt.Sprintf("agentusage.Delta{full: %t, empty: %t, files: %d}", d.full, d.Empty(), len(d.files))
268	}
269	
270	// GoString shows counts only.
271	func (d Delta) GoString() string { return d.String() }
272	
273	// Aggregate is a session's usage built from successive deltas. It is not safe
274	// for concurrent use: one goroutine (Bubble Tea's Update) owns it.
275	type Aggregate struct {
276		parent    string
277		id, seq   uint64
278		fresh     bool
279		sessionID string
280		files     []fileCursor // parent first, then sub-agents by rank
281		metas     []metaCursor
282		t         *table
283	}
284	
285	// NewAggregate starts an empty aggregate for the session whose parent
286	// transcript is parentTranscript (<dir>/<uuid>.jsonl). It does no I/O.
287	func NewAggregate(parentTranscript string) *Aggregate {
288		base := filepath.Base(parentTranscript)
289		return &Aggregate{
290			parent:    parentTranscript,
291			id:        aggregateIDs.Add(1),
292			fresh:     true,
293			sessionID: sanitizeLabel(strings.TrimSuffix(base, transcriptExt)),
294			files:     []fileCursor{newFileCursor(parentTranscript, sanitizeLabel(base), "", parentRank)},
295			t:         newTable(),
296		}
297	}
298	
299	// Cursor returns a copy of the aggregate's position, to hand to ReadDelta.
300	func (a *Aggregate) Cursor() Cursor {
301		return Cursor{
302			parent: a.parent, id: a.id, seq: a.seq, fresh: a.fresh,
303			files: slices.Clone(a.files), metas: slices.Clone(a.metas),
304		}
305	}
306	
307	// Apply folds d in, or replaces everything with it when d.Full(). It returns
308	// ErrStaleDelta, and changes nothing, if d was not read from a.Cursor(). It
309	// takes ownership of d.
310	func (a *Aggregate) Apply(d Delta) error {
311		if !d.valid || d.id != a.id || d.seq != a.seq {
312			return ErrStaleDelta
313		}
314		switch {
315		case d.full:
316			a.t = boundedTable(d.part)
317		case d.part != nil:
318			a.t.mergeCapped(d.part)
319		}
320		a.files, a.metas, a.sessionID = d.files, d.metas, d.sessionID
321		a.fresh = false
322		a.seq++
323		return nil
324	}
325	
326	// boundedTable returns part, or a copy of it holding at most maxNoIDEntries
327	// entries without a message id.
328	func boundedTable(part *table) *table {
329		if part == nil {
330			return newTable()
331		}
332		if part.noID <= maxNoIDEntries {
333			return part
334		}
335		t := newTable()
336		t.mergeCapped(part)
337		return t
338	}
339	
340	// Usage returns the session's usage so far, same shape and rules as
341	// ParseSession; the result shares no memory with the aggregate.
342	func (a *Aggregate) Usage() Usage {
343		agents := []Agent{{Main: true, State: StateUnknown}}
344		var diag Diagnostics
345		var truncated []string
346		var issues []issueAt
347		metaOf := make(map[string]metaCursor, len(a.metas))
348		for _, m := range a.metas {
349			metaOf[m.rank] = m
350		}
351		for _, fc := range a.files {
352			if fc.tail {
353				truncated = append(truncated, fc.name)
354			}
355			if fc.hasIssue {
356				fi := FileIssue{File: fc.name, Offset: fc.issueOff, Kind: fc.issue}
357				issues = append(issues, issueAt{p: pos{rank: fc.rank, off: fc.issueOff}, fi: fi})
358			}
359			if fc.rank != parentRank {
360				agents = append(agents, subAgent(fc, metaOf[fc.rank], &diag))
361			}
362		}
363		agents, diag2, versions := a.t.finishWith(agents, issues)
364		diag2.MetaMissing, diag2.MetaUnreadable, diag2.TruncatedFiles = diag.MetaMissing, diag.MetaUnreadable, truncated
365		return Usage{SessionID: a.sessionID, Agents: agents, Versions: versions, Diagnostics: diag2}
366	}
367	
368	// subAgent builds a sub-agent's identity from its meta cursor, counting a
369	// missing or unreadable meta file in diag.
370	func subAgent(fc fileCursor, m metaCursor, diag *Diagnostics) Agent {
371		ag := Agent{ID: fc.label, key: fc.rank}
372		switch {
373		case m.path == "":
374			diag.MetaMissing++
375		case m.unreadable:
376			diag.MetaUnreadable++
377		default:
378			ag.Type, ag.State, ag.SpawnDepth = m.typ, m.state, m.depth
379		}
380		return ag
381	}
382	
383	// ReadDelta lists the session again (parent, subagents/, meta files, Lstat
384	// only) and reads what was appended since c. Files whose size did not change
385	// are not opened. It fails only if the parent transcript is missing, a link,
386	// not a regular file, or the session cannot be listed; errors name base names
387	// only. On error there is nothing to apply.
388	func ReadDelta(c Cursor) (Delta, error) {
389		files, infos, err := listForPoll(c.parent)
390		if err != nil {
391			return Delta{}, err
392		}
393		return readSession(files, infos, c, timeNow()), nil
394	}
395	
396	// listForPoll lists the session like LocateSession, with meta presence from
397	// Lstat only (D7), and returns the Lstat result of each meta file found.
398	func listForPoll(parent string) (SessionFiles, map[string]os.FileInfo, error) {
399		infos := map[string]os.FileInfo{}
400		files, err := locateSession(parent, func(path string) bool {
401			fi, err := os.Lstat(path)
402			if err != nil || !fi.Mode().IsRegular() {
403				return false
404			}
405			infos[path] = fi
406			return true
407		})
408		return files, infos, err
409	}
410	
411	// target is one transcript of a listing, with its meta file ("" if absent).
412	type target struct {
413		fc   fileCursor
414		meta string
415	}
416	
417	// sessionTargets turns a listing into fresh cursors: the parent first, then
418	// the sub-agents in rank order, which is the order ParseSession reads them.
419	func sessionTargets(files SessionFiles) []target {
420		out := []target{{fc: newFileCursor(files.Parent, sanitizeLabel(filepath.Base(files.Parent)), "", parentRank)}}
421		for _, sa := range files.SubAgents {
422			id := sanitizeLabel(sa.ID)
423			name := sanitizeLabel(filepath.Base(sa.Transcript))
424			rank := transcriptRank(id, name, sa.ID, sa.Transcript)
425			fc := newFileCursor(sa.Transcript, name, rank, rank)
426			fc.label = id
427			out = append(out, target{fc: fc, meta: sa.Meta})
428		}
429		slices.SortFunc(out[1:], func(a, b target) int { return cmp.Compare(a.fc.rank, b.fc.rank) })
430		return out
431	}
432	
433	// readSession reads the files of a listing from c. A change that is not an
434	// append (D4) restarts every file from the start and the delta is Full.
435	// ParseSession passes a fresh cursor and no meta Lstat information.
436	func readSession(files SessionFiles, infos map[string]os.FileInfo, c Cursor, now time.Time) Delta {
437		targets := sessionTargets(files)
438		full := c.fresh
439		p, ok := readTargets(targets, c, now)
440		if !ok {
441			c, full = c.Rewound(), true
442			p, _ = readTargets(targets, c, now)
443		}
444		metas, metaChanged := readMetas(targets[1:], infos, c)
445		return Delta{
446			valid: true, id: c.id, seq: c.seq, full: full,
447			changed:   full || p.changed || metaChanged,
448			sessionID: sanitizeLabel(files.ID),
449			files:     p.files, metas: metas, part: p.part, parentErr: p.parentErr,
450		}
451	}
452	
453	// sessionPass is the outcome of one pass over the transcripts.
454	type sessionPass struct {
455		files     []fileCursor
456		part      *table
457		changed   bool
458		parentErr error
459	}
460	
461	// readTargets reads every target from its cursor in c, or from the start when
462	// c does not know it. ok is false when a file asks for a restart (D4): a
463	// file read before is gone, or was not simply appended to.
464	func readTargets(targets []target, c Cursor, now time.Time) (sessionPass, bool) {
465		prior := make(map[string]fileCursor, len(c.files))
466		for _, fc := range c.files {
467			prior[fc.rank] = fc
468		}
469		var p sessionPass
470		for _, tg := range targets {
471			fc, had := prior[tg.fc.rank]
472			delete(prior, tg.fc.rank)
473			if !had {
474				fc, p.changed = tg.fc, true
475			}
476			fr := readFile(fc, now)
477			if fr.reset {
478				return sessionPass{}, false
479			}
480			if fr.next.rank == parentRank && fr.err != nil {
481				p.parentErr = fr.err
482			}
483			p.changed = p.changed || fr.part != nil || fc.issueState() != fr.next.issueState()
484			p.files = append(p.files, fr.next)
485			p.addPart(fr.part)
486		}
487		for _, gone := range prior {
488			if gone.read() {
489				return sessionPass{}, false
490			}
491			p.changed = true
492		}
493		return p, true
494	}
495	
496	// addPart folds the lines of one file into the pass.
497	func (p *sessionPass) addPart(part *table) {
498		switch {
499		case part == nil:
500		case p.part == nil:
501			p.part = part
502		default:
503			p.part.merge(part)
504		}
505	}
506	
507	// issueState is what a cursor says about its last read, for comparisons.
508	type issueState struct {
509		has  bool
510		kind IssueKind
511		off  int64
512	}
513	
514	func (fc fileCursor) issueState() issueState {
515		return issueState{has: fc.hasIssue, kind: fc.issue, off: fc.issueOff}
516	}
517	
518	// readMetas returns the meta cursors of the sub-agents in targets, reading a
519	// meta file only when its Lstat size or mtime differs from c's (D7), and
520	// whether any of them tells something new.
521	func readMetas(subs []target, infos map[string]os.FileInfo, c Cursor) ([]metaCursor, bool) {
522		prior := make(map[string]metaCursor, len(c.metas))
523		for _, m := range c.metas {
524			prior[m.rank] = m
525		}
526		out := make([]metaCursor, 0, len(subs))
527		changed := false
528		for _, tg := range subs {
529			m := nextMeta(tg, infos, prior)
530			old, had := prior[m.rank]
531			changed = changed || !had || !old.sameResult(m)
532			out = append(out, m)
533		}
534		return out, changed
535	}
536	
537	// nextMeta returns the meta cursor of one sub-agent: the prior one when its
538	// file did not change, else a fresh read through readMetaFile.
539	func nextMeta(tg target, infos map[string]os.FileInfo, prior map[string]metaCursor) metaCursor {
540		m := metaCursor{rank: tg.fc.rank}
541		if tg.meta == "" {
542			return m
543		}
544		m.path = tg.meta
545		fi := infos[tg.meta]
546		if fi != nil {
547			m.size, m.modTime = fi.Size(), fi.ModTime()
548		}
549		if old, ok := prior[m.rank]; ok && old.unchangedSince(tg.meta, fi) {
550			return old
551		}
552		md, err := readMetaFile(tg.meta)
553		if err != nil {
554			m.unreadable = true
555			return m
556		}
557		m.typ, m.state, m.depth = md.AgentType, md.state(), md.SpawnDepth
558		return m
559	}
560

