40	// transcriptFile is what readFile needs from an open transcript; *os.File
41	// satisfies it.
42	type transcriptFile interface {
43		io.Reader
44		io.ReaderAt
45		io.Seeker
46		io.Closer
47		Stat() (os.FileInfo, error)
48	}
49	
50	// openTranscript opens a transcript through openPlain. A var so tests can
51	// count opens and bytes read.
52	var openTranscript = func(path string) (transcriptFile, error) {
53		f, err := openPlain(path, false)
54		if err != nil {
55			return nil, err
56		}
57		if f == nil {
58			return nil, errNotRegular
59		}
60		return f, nil
61	}
62	
63	// fileRead is the outcome of reading one file from its cursor.
64	type fileRead struct {
65		next  fileCursor
66		part  *table // lines folded from the new bytes; nil when nothing was read
67		reset bool   // not an append (D4): the caller restarts the whole session
68		err   error  // why the file could not be opened or read at all, if so
69	}
70	
71	// read reports whether the cursor has already read part of its file.
72	func (fc fileCursor) read() bool { return fc.offset > 0 || fc.skipFrom >= 0 || fc.id != nil }
73	
74	// quiet reports whether the file is, as far as Lstat can tell, exactly what the
75	// last read saw. A cursor holding a read error never is: the bytes between
76	// its offset and the failure must be read again.
77	func (fc fileCursor) quiet(li os.FileInfo) bool {
78		if fc.id == nil || (fc.hasIssue && fc.issue == IssueReadError) {
79			return false
80		}
81		return li.Size() == fc.size && os.SameFile(li, fc.id)
82	}
83	
84	// failRead is the outcome of a path that cannot be read: a reset when the file
85	// was read before (D4), else a state issue cleared by the next success (D6).
86	func failRead(fc fileCursor, err error) fileRead {
87		if fc.read() {
88			return fileRead{next: fc, reset: true, err: err}
89		}
90		fc.issue, fc.issueOff, fc.hasIssue = IssueOpenFailed, 0, true
91		return fileRead{next: fc, err: err}
92	}
93	
94	// isAppend reports whether the open file is the one fc read, only grown (D4).
95	func (fc fileCursor) isAppend(f transcriptFile, fi os.FileInfo) bool {
96		if (fc.id != nil && !os.SameFile(fi, fc.id)) || fi.Size() < fc.size {
97			return false
98		}
99		if fc.offset == 0 {
100			return true
101		}
102		var b [1]byte
103		n, _ := f.ReadAt(b[:], fc.offset-1)
104		return n == 1 && b[0] == '\n'
105	}
106	
107	// readFile reads what was appended to fc's file since fc. now clamps mtimes.
108	// It never follows a link and never opens a non-regular file.
109	func readFile(fc fileCursor, now time.Time) fileRead {
110		li, err := os.Lstat(fc.path)
111		if err != nil {
112			return failRead(fc, err)
113		}
114		if !li.Mode().IsRegular() {
115			return failRead(fc, errNotRegular)
116		}
117		fc.modTime = li.ModTime()
118		if fc.modTime.After(now) {
119			fc.modTime = now
120		}
121		if fc.quiet(li) {
122			return fileRead{next: fc}
123		}
124		f, err := openTranscript(fc.path)
125		if err != nil {
126			return failRead(fc, err)
127		}
128		defer func() { _ = f.Close() }()
129		fi, err := f.Stat()
130		if err != nil {
131			return failRead(fc, err)
132		}
133		if !fc.isAppend(f, fi) {
134			return fileRead{next: fc, reset: true}
135		}
136		return fc.scan(f, fi)
137	}
138	
139	// scan folds the lines past the cursor into a new table and returns the
140	// advanced cursor. A line held back is read again next time (D1); an
141	// oversized one still being written is resumed in skip mode (D2).
142	func (fc fileCursor) scan(f transcriptFile, fi os.FileInfo) fileRead {
143		start := fc.offset
144		if fc.skipFrom >= 0 {
145			start = fc.size
146		}
147		if _, err := f.Seek(start, io.SeekStart); err != nil {
148			return failRead(fc, err)
149		}
150		part := newTable()
151		res, err := scanFrom(f, start, fc.skipFrom, MaxLineBytes, func(line []byte, off int64) {
152			part.addLine(fc.agent, fc.name, pos{rank: fc.rank, off: off}, line)
153		})
154		for _, off := range res.OversizedAt {
155			part.addOversized(fc.name, pos{rank: fc.rank, off: off})
156		}
157		next := fc
158		next.id, next.size, next.skipFrom = fi, res.End, res.SkipFrom
159		next.offset, next.tail = res.Consumed, len(res.Tail) > 0
160		if fc.skipFrom >= 0 && res.Consumed == start {
161			next.offset = fc.offset // the oversized line has not ended yet
162		}
163		next.issue, next.issueOff, next.hasIssue = 0, 0, false
164		if err != nil {
165			next.issue, next.issueOff, next.hasIssue = IssueReadError, next.offset, true
166		}
167		return fileRead{next: next, part: part}
168	}
169	
170	// ErrStaleDelta is returned by Apply for a delta that was not read from the
171	// aggregate's current cursor. The aggregate is unchanged; read again from
172	// Cursor().
173	var ErrStaleDelta = errors.New("agentusage: delta does not follow the aggregate's cursor")
174	
175	// readMetaFile reads one meta file; a var so tests can count meta reads (D7).
176	// The session reader goes through it.
177	var readMetaFile = readMeta
178	
179	// timeNow is time.Now; a var for tests.
180	var timeNow = time.Now
181	
182	// aggregateIDs hands out the identity of each Aggregate (D9).
183	var aggregateIDs atomic.Uint64
184	
185	// metaCursor is the last listing of one sub-agent's meta file and what was
186	// read from it. Values only, so a cursor stays a plain copyable value.
187	type metaCursor struct {
188		rank       string // rank of the sub-agent's transcript
189		path       string // "" when absent
190		size       int64
191		modTime    time.Time
192		unreadable bool
193		typ        string
194		state      State
195		depth      int
196	}
197	
198	// sameResult reports whether o tells the same story as m: Lstat details such
199	// as the mtime are not part of it.
200	func (m metaCursor) sameResult(o metaCursor) bool {
201		return m.rank == o.rank && (m.path == "") == (o.path == "") && m.unreadable == o.unreadable &&
202			m.typ == o.typ && m.state == o.state && m.depth == o.depth
203	}
204	
205	// unchangedSince reports whether the file Lstat described by fi is the one m
206	// was read from.
207	func (m metaCursor) unchangedSince(path string, fi os.FileInfo) bool {
208		return fi != nil && m.path == path && m.size == fi.Size() && m.modTime.Equal(fi.ModTime())
209	}
