1	package agentusage
2	
3	import (
4		"errors"
5		"fmt"
6		"io/fs"
7		"os"
8		"path/filepath"
9		"sort"
10		"strings"
11	)
12	
13	const (
14		transcriptExt = ".jsonl"
15		metaExt       = ".meta.json"
16		agentPrefix   = "agent-"
17		subagentsDir  = "subagents"
18	)
19	
20	// SubAgentFiles locates one sub-agent's files; Meta is "" if absent.
21	type SubAgentFiles struct{ ID, Transcript, Meta string }
22	
23	// SessionFiles locates a session's transcripts.
24	type SessionFiles struct {
25		ID, Parent string
26		SubAgents  []SubAgentFiles
27	}
28	
29	// ProjectsRoot returns the Claude Code projects directory:
30	// $CLAUDE_CONFIG_DIR/projects, else ~/.claude/projects.
31	func ProjectsRoot() (string, error) {
32		if dir := os.Getenv("CLAUDE_CONFIG_DIR"); dir != "" {
33			return filepath.Join(dir, "projects"), nil
34		}
35		home, err := os.UserHomeDir()
36		if err != nil {
37			return "", err
38		}
39		return filepath.Join(home, ".claude", "projects"), nil
40	}
41	
42	// LocateSession finds the sub-agent files of the session whose parent
43	// transcript is <dir>/<uuid>.jsonl, looking in <dir>/<uuid>/subagents/. A
44	// missing session directory means no sub-agents. Symbolic links are ignored
45	// and nothing is searched recursively.
46	func LocateSession(parentTranscript string) (SessionFiles, error) {
47		return locateSession(parentTranscript, metaOpens)
48	}
49	
50	// metaPresence tells whether the meta file at path exists as a plain file.
51	type metaPresence func(path string) bool
52	
53	// metaOpens checks a meta file by opening it through openPlain.
54	func metaOpens(path string) bool {
55		mf, _ := openPlain(path, false)
56		if mf == nil {
57			return false
58		}
59		_ = mf.Close()
60		return true
61	}
62	
63	// locateSession is LocateSession with the meta presence check chosen by the
64	// caller: a poller passes an Lstat-only one so it never opens a meta file.
65	func locateSession(parentTranscript string, present metaPresence) (SessionFiles, error) {
66		base := filepath.Base(parentTranscript)
67		if !strings.HasSuffix(base, transcriptExt) {
68			return SessionFiles{}, fmt.Errorf("agentusage: %s does not end in %s", base, transcriptExt)
69		}
70		info, err := os.Lstat(parentTranscript)
71		if err != nil {
72			return SessionFiles{}, baseOnly(err)
73		}
74		if !info.Mode().IsRegular() {
75			return SessionFiles{}, fmt.Errorf("agentusage: %s is not a regular file", base)
76		}
77		id := strings.TrimSuffix(base, transcriptExt)
78		if id == "" {
79			return SessionFiles{}, fmt.Errorf("agentusage: %s has no session id", base)
80		}
81		files := SessionFiles{ID: sanitizeLabel(id), Parent: parentTranscript}
82		sessionDir := filepath.Join(filepath.Dir(parentTranscript), id)
83		if fi, err := os.Lstat(sessionDir); err != nil || !fi.IsDir() {
84			if err == nil || errors.Is(err, os.ErrNotExist) {
85				return files, nil // absent, or a link: no sub-agents
86			}
87			return files, baseOnly(err)
88		}
89		files.SubAgents, err = subAgentFiles(filepath.Join(sessionDir, subagentsDir), present)
90		return files, baseOnly(err)
91	}
92	
93	// subAgentFiles lists agent-<id>.jsonl files directly inside dir, sorted by
94	// ID, each with its meta file if one exists. A missing dir or a symbolic
95	// link yields nothing.
96	func subAgentFiles(dir string, present metaPresence) ([]SubAgentFiles, error) {
97		f, err := openPlain(dir, true)
98		if f == nil {
99			if err == nil || errors.Is(err, os.ErrNotExist) {
100				return nil, nil
101			}
102			return nil, err
103		}
104		defer func() { _ = f.Close() }()
105		entries, err := f.ReadDir(-1)
106		if err != nil {
107			return nil, err
108		}
109		var out []SubAgentFiles
110		for _, e := range entries {
111			if sa, ok := subAgentEntry(dir, e, present); ok {
112				out = append(out, sa)
113			}
114		}
115		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
116		return out, nil
117	}
118	
119	// subAgentEntry turns a directory entry into a sub-agent, if it is a
120	// regular agent-<id>.jsonl file.
121	func subAgentEntry(dir string, e os.DirEntry, present metaPresence) (SubAgentFiles, bool) {
122		name := e.Name()
123		if !e.Type().IsRegular() || !strings.HasPrefix(name, agentPrefix) || !strings.HasSuffix(name, transcriptExt) {
124			return SubAgentFiles{}, false
125		}
126		id := strings.TrimSuffix(strings.TrimPrefix(name, agentPrefix), transcriptExt)
127		if id == "" {
128			return SubAgentFiles{}, false
129		}
130		sa := SubAgentFiles{ID: sanitizeLabel(id), Transcript: filepath.Join(dir, name)}
131		metaPath := filepath.Join(dir, agentPrefix+id+metaExt)
132		if present(metaPath) {
133			sa.Meta = metaPath
134		}
135		return sa, true
136	}
137	
138	// baseOnly rewrites a path error so it names the base name of the file, not
139	// the full path; errors.Is and errors.As on the cause keep working.
140	func baseOnly(err error) error {
141		var pe *fs.PathError
142		if errors.As(err, &pe) {
143			return &fs.PathError{Op: pe.Op, Path: filepath.Base(pe.Path), Err: pe.Err}
144		}
145		return err
146	}
