1	package agentusage
2	
3	import (
4		"cmp"
5		"slices"
6	)
7	
8	// pos orders lines the way ParseSession reads them (D3).
9	type pos struct {
10		rank string // "0" parent; "1"+agentID+"\x00"+baseName for a sub-agent
11		off  int64
12	}
13	
14	// parentRank is the rank of the parent transcript; it sorts before every
15	// sub-agent rank.
16	const parentRank = "0"
17	
18	// subAgentRank is the rank of a sub-agent's transcript: sub-agents are read by
19	// ID, then by base name.
20	func subAgentRank(agentID, name string) string { return "1" + agentID + "\x00" + name }
21	
22	// transcriptRank is subAgentRank made unique per transcript: the raw ID and
23	// the path break ties between sub-agents whose sanitized IDs and base names
24	// coincide. It is a function of the transcript alone, so it is stable from one
25	// pass to the next, and it doubles as the agent's key in a table.
26	func transcriptRank(agentID, name, rawID, path string) string {
27		return subAgentRank(agentID, name) + "\x00" + rawID + "\x00" + path
28	}
29	
30	// compare orders positions by rank, then by offset.
31	func (p pos) compare(o pos) int {
32		if c := cmp.Compare(p.rank, o.rank); c != 0 {
33			return c
34		}
35		return cmp.Compare(p.off, o.off)
36	}
37	
38	// msgKey identifies one message of a session. A message with an id is keyed
39	// by the id alone; one without is keyed by where it was read (file rank and
40	// offset).
41	type msgKey struct {
42		id   string
43		file string
44		off  int64
45	}
46	
47	// entry is the last state seen of one message. Which line is "last" is a
48	// function of positions, never of arrival.
49	type entry struct {
50		first, last pos
51		agent       string // agent ID of the last line; "" for the parent
52		file        string // base name of one file the message was seen in
53		otherFiles  []string
54		model       string
55		tokens      Tokens
56		stopNull    bool
57	}
58	
59	// addFile remembers that the message was also seen in the file named name.
60	func (e *entry) addFile(name string) {
61		if e.file == name || slices.Contains(e.otherFiles, name) {
62			return
63		}
64		e.otherFiles = append(e.otherFiles, name)
65	}
66	
67	// absorb folds o into e: the greatest position gives the state, the smallest
68	// gives first, and the files are united.
69	func (e *entry) absorb(o *entry) {
70		if o.last.compare(e.last) >= 0 {
71			e.last, e.agent, e.model, e.tokens, e.stopNull = o.last, o.agent, o.model, o.tokens, o.stopNull
72		}
73		if o.first.compare(e.first) < 0 {
74			e.first = o.first
75		}
76		e.addFile(o.file)
77		for _, f := range o.otherFiles {
78			e.addFile(f)
79		}
80	}
81	
82	// spill totals the lines that no longer get a table entry.
83	type spill struct {
84		tokens   Tokens
85		messages int
86		partial  int
87		models   modelSet
88	}
89	
90	// issueAt is a FileIssue with the position of the line it describes.
91	type issueAt struct {
92		p  pos
93		fi FileIssue
94	}
95	
96	// compare orders issues by position, then kind, then file.
97	func (a issueAt) compare(b issueAt) int {
98		if c := a.p.compare(b.p); c != 0 {
99			return c
100		}
101		if c := cmp.Compare(a.fi.Kind, b.fi.Kind); c != 0 {
102			return c
103		}
104		return cmp.Compare(a.fi.File, b.fi.File)
105	}
106	
107	// table folds lines into per-key last states, ordered by position (D3). It
108	// is both the content of a Delta and the state of an Aggregate. Two declared
109	// exceptions to order-freedom: which no-id lines spill past maxNoIDEntries,
110	// and which models fill a spill's maxModelsPerAgent, follow arrival order.
111	type table struct {
112		entries map[msgKey]*entry
113		noID    int // entries holding a line without message id
114		spill   map[string]*spill
115		// counters of lines; CrossFileDuplicates is derived by finish.
116		unreadable, noUsage, noMessageID, oversized int
117		// capped holds the unreadable/oversized issues per file name, trimmed to
118		// the maxFileIssuesPerFile smallest positions; stateIssues holds the
119		// other kinds, which occur once per file.
120		capped      map[string][]issueAt
121		stateIssues []issueAt
122		// versions maps a distinct client version to its first position, at most
123		// maxVersions of them (the smallest positions).
124		versions map[string]pos
125	}
126	
127	func newTable() *table {
128		return &table{
129			entries:  map[msgKey]*entry{},
130			spill:    map[string]*spill{},
131			capped:   map[string][]issueAt{},
132			versions: map[string]pos{},
133		}
134	}
135	
136	// addLine decodes one line of the file named name for agent ("" for the
137	// parent) and folds it. Synthetic and ignored lines never count.
138	func (t *table) addLine(agent, name string, p pos, line []byte) {
139		r, kind := decodeLine(line)
140		if kind != kindUnreadable {
141			t.noteVersion(r.Version, p)
142		}
143		switch kind {
144		case kindUsage:
145			t.addUsage(agent, name, p, r)
146		case kindNoUsage:
147			t.noUsage++
148		case kindUnreadable:
149			t.unreadable++
150			t.addFileIssue(name, p, IssueUnreadable)
151		case kindIgnored, kindSynthetic:
152		}
153	}
154	
155	// addOversized counts a line longer than MaxLineBytes that started at p.
156	func (t *table) addOversized(name string, p pos) {
157		t.oversized++
158		t.addFileIssue(name, p, IssueOversized)
159	}
160	
161	// addUsage folds one usage record in.
162	func (t *table) addUsage(agent, name string, p pos, r record) {
163		key := msgKey{id: r.MessageID}
164		if r.MessageID == "" {
165			key = msgKey{file: p.rank, off: p.off}
166			t.noMessageID++
167			if _, ok := t.entries[key]; !ok {
168				if t.noID >= maxNoIDEntries {
169					t.addSpill(agent, r)
170					return
171				}
172				t.noID++
173			}
174		}
175		t.put(key, &entry{
176			first: p, last: p, agent: agent, file: name,
177			model: r.Model, tokens: r.Usage, stopNull: r.StopNull,
178		})
179	}
180	
181	// put folds e into the table under key; the table keeps its own copy.
182	func (t *table) put(key msgKey, e *entry) {
183		if cur, ok := t.entries[key]; ok {
184			cur.absorb(e)
185			return
186		}
187		c := *e
188		c.otherFiles = slices.Clone(e.otherFiles)
189		t.entries[key] = &c
190	}
191	
192	// addSpill counts a no-id line that gets no table entry.
193	func (t *table) addSpill(agent string, r record) {
194		sp := t.spill[agent]
195		if sp == nil {
196			sp = &spill{}
197			t.spill[agent] = sp
198		}
199		sp.absorbRecord(r)
200	}
201	
202	// spillEntry totals an entry that gets no slot in the table.
203	func (t *table) spillEntry(e *entry) {
204		sp := t.spill[e.agent]
205		if sp == nil {
206			sp = &spill{}
207			t.spill[e.agent] = sp
208		}
209		sp.tokens = sp.tokens.Add(e.tokens)
210		sp.messages++
211		if e.stopNull {
212			sp.partial++
213		}
214		sp.models.add(e.model)
215	}
216	
217	func (s *spill) absorbRecord(r record) {
218		s.tokens = s.tokens.Add(r.Usage)
219		s.messages++
220		if r.StopNull {
221			s.partial++
222		}
223		s.models.add(r.Model)
224	}
225	
226	// noteVersion records a client version with its first position, keeping the
227	// maxVersions smallest.
228	func (t *table) noteVersion(v string, p pos) {
229		v = sanitizeLabel(v)
230		if v == "" {
231			return
232		}
233		if cur, ok := t.versions[v]; ok {
234			if p.compare(cur) < 0 {
235				t.versions[v] = p
236			}
237			return
238		}
239		if len(t.versions) >= maxVersions {
240			worst, wp := "", pos{}
241			for k, kp := range t.versions {
242				if worst == "" || kp.compare(wp) > 0 {
243					worst, wp = k, kp
244				}
245			}
246			if p.compare(wp) >= 0 {
247				return
248			}
249			delete(t.versions, worst)
250		}
251		t.versions[v] = p
252	}
253	
254	// addFileIssue records an issue of the file named name. Unreadable and
255	// oversized ones are kept at most maxFileIssuesPerFile per file (the counters
256	// are not capped); the other kinds occur once per file and are always kept.
257	func (t *table) addFileIssue(name string, p pos, kind IssueKind) {
258		it := issueAt{p: p, fi: FileIssue{File: name, Offset: p.off, Kind: kind}}
259		if kind != IssueUnreadable && kind != IssueOversized {
260			t.stateIssues = append(t.stateIssues, it)
261			return
262		}
263		t.capped[name] = trimIssues(append(t.capped[name], it), 2*maxFileIssuesPerFile)
264	}
265	
266	// trimIssues keeps the maxFileIssuesPerFile smallest issues once s has grown
267	// to limit entries.
268	func trimIssues(s []issueAt, limit int) []issueAt {
269		if len(s) < limit {
270			return s
271		}
272		slices.SortFunc(s, issueAt.compare)
273		return s[:min(len(s), maxFileIssuesPerFile)]
274	}
275	
276	// merge folds o into t as if o's lines had been added to t. o is not modified
277	// and shares nothing with t afterwards.
278	func (t *table) merge(o *table) { t.mergeSkipping(o, nil) }
279	
280	// mergeCapped is merge with the per-session bound on lines without id: the
281	// ones o adds past maxNoIDEntries are spilled instead of getting an entry,
282	// the earliest positions being kept. Which lines spill therefore follows
283	// position, not arrival, but the totals do not depend on it.
284	func (t *table) mergeCapped(o *table) {
285		var fresh []msgKey
286		for k := range o.entries {
287			if _, had := t.entries[k]; k.id == "" && !had {
288				fresh = append(fresh, k)
289			}
290		}
291		room := max(maxNoIDEntries-t.noID, 0)
292		if len(fresh) <= room {
293			t.merge(o)
294			return
295		}
296		slices.SortFunc(fresh, func(a, b msgKey) int { return o.entries[a].first.compare(o.entries[b].first) })
297		skip := make(map[msgKey]bool, len(fresh)-room)
298		for _, k := range fresh[room:] {
299			skip[k] = true
300		}
301		t.mergeSkipping(o, skip)
302	}
303	
304	// mergeSkipping is merge, except that the entries named by skip are spilled.
305	func (t *table) mergeSkipping(o *table, skip map[msgKey]bool) {
306		for k, e := range o.entries {
307			if skip[k] {
308				t.spillEntry(e)
309				continue
310			}
311			_, had := t.entries[k]
312			t.put(k, e)
313			if !had && k.id == "" {
314				t.noID++
315			}
316		}
317		for agent, sp := range o.spill {
318			dst := t.spill[agent]
319			if dst == nil {
320				dst = &spill{}
321				t.spill[agent] = dst
322			}
323			dst.tokens = dst.tokens.Add(sp.tokens)
324			dst.messages += sp.messages
325			dst.partial += sp.partial
326			for _, m := range sp.models.list {
327				dst.models.add(m)
328			}
329		}
330		t.unreadable += o.unreadable
331		t.noUsage += o.noUsage
332		t.noMessageID += o.noMessageID
333		t.oversized += o.oversized
334		for name, s := range o.capped {
335			t.capped[name] = trimIssues(append(t.capped[name], s...), 2*maxFileIssuesPerFile)
336		}
337		t.stateIssues = append(t.stateIssues, o.stateIssues...)
338		for v, p := range o.versions {
339			t.noteVersion(v, p)
340		}
341	}
342	
343	// orderedKeys returns the entry keys by first position: the order messages
344	// first appear in a sequential read.
345	func (t *table) orderedKeys() []msgKey {
346		keys := make([]msgKey, 0, len(t.entries))
347		for k := range t.entries {
348			keys = append(keys, k)
349		}
350		slices.SortFunc(keys, func(a, b msgKey) int {
351			if c := t.entries[a].first.compare(t.entries[b].first); c != 0 {
352				return c
353			}
354			return cmp.Or(cmp.Compare(a.id, b.id), cmp.Compare(a.file, b.file), cmp.Compare(a.off, b.off))
355		})
356		return keys
357	}
358	
359	// finish computes the counters of the agents given (identity fields set, the
360	// parent flagged Main), the line diagnostics and the versions, all deep
361	// copies. Agents are matched by key (ID when unset); the Main agent matches
362	// the parent's "".
363	func (t *table) finish(agents []Agent) ([]Agent, Diagnostics, []string) {
364		return t.finishWith(agents, nil)
365	}
366	
367	// finishWith is finish with extra file issues, kept in position order among
368	// the table's own: a session reader passes the states of its cursors.
369	func (t *table) finishWith(agents []Agent, extra []issueAt) ([]Agent, Diagnostics, []string) {
370		out := slices.Clone(agents)
371		idx := make(map[string]int, len(out))
372		for i := range out {
373			out[i].Tokens, out[i].Models = Tokens{}, nil
374			out[i].Messages, out[i].PartialMessages = 0, 0
375			id := cmp.Or(out[i].key, out[i].ID)
376			if out[i].Main {
377				id = ""
378			}
379			out[i].key = ""
380			idx[id] = i
381		}
382		models := make([]modelSet, len(out))
383		cross := 0
384		for _, k := range t.orderedKeys() {
385			e := t.entries[k]
386			cross += len(e.otherFiles)
387			if i, ok := idx[e.agent]; ok {
388				addEntry(&out[i], &models[i], e)
389			}
390		}
391		for agent, sp := range t.spill {
392			if i, ok := idx[agent]; ok {
393				addSpill(&out[i], &models[i], sp)
394			}
395		}
396		for i := range out {
397			out[i].Models = models[i].list
398		}
399		return out, t.diagnostics(cross, extra), t.orderedVersions()
400	}
401	
402	// addEntry adds one message's final state to its agent.
403	func addEntry(ag *Agent, ms *modelSet, e *entry) {
404		ag.Tokens = ag.Tokens.Add(e.tokens)
405		ag.Messages++
406		if e.stopNull {
407			ag.PartialMessages++
408		}
409		ms.add(e.model)
410	}
411	
412	// addSpill adds a spill's totals to its agent.
413	func addSpill(ag *Agent, ms *modelSet, sp *spill) {
414		ag.Tokens = ag.Tokens.Add(sp.tokens)
415		ag.Messages += sp.messages
416		ag.PartialMessages += sp.partial
417		for _, m := range sp.models.list {
418			ms.add(m)
419		}
420	}
421	
422	// diagnostics builds the line diagnostics; cross is the number of cross-file
423	// duplicates found by finish and extra holds issues that are not the table's.
424	func (t *table) diagnostics(cross int, extra []issueAt) Diagnostics {
425		d := Diagnostics{
426			UnreadableLines: t.unreadable, OversizedLines: t.oversized,
427			NoUsage: t.noUsage, NoMessageID: t.noMessageID, CrossFileDuplicates: cross,
428		}
429		all := append(slices.Clone(t.stateIssues), extra...)
430		for _, s := range t.capped {
431			sorted := slices.Clone(s)
432			slices.SortFunc(sorted, issueAt.compare)
433			all = append(all, sorted[:min(len(sorted), maxFileIssuesPerFile)]...)
434		}
435		slices.SortFunc(all, issueAt.compare)
436		for _, it := range all {
437			d.Files = append(d.Files, it.fi)
438		}
439		return d
440	}
441	
442	// orderedVersions returns the versions by first position.
443	func (t *table) orderedVersions() []string {
444		var vs []string
445		for v := range t.versions {
446			vs = append(vs, v)
447		}
448		slices.SortFunc(vs, func(a, b string) int { return t.versions[a].compare(t.versions[b]) })
449		return vs
450	}
